from collections.abc import Iterable


def collapse_lines(lines: Iterable[str]) -> list[str]:
    """去掉空行、首尾空白，保持中间非空行的顺序。"""
    out: list[str] = []
    for line in lines:
        text = line.strip()
        if text and text not in out:
            out.append(text)
    return out


if __name__ == '__main__':
    print(collapse_lines([' a b', '', 'c', ' a b']))
